  retroCustomColors: false,
  retroDarkBgColor: "#141010",
  retroDarkTextColor: "#f2f2f2",
  retroLightBgColor: "#e9e8e8",
  retroLightTextColor: "#f7fb09",
  // The bar's top and bottom rules. Their own colours now rather than
