          const bb = bubbles[bi];
          bb.y -= bb.rise * (bb.size === 2 ? 1.5 : 1) * f.dt;
          bb.phase += f.dt * 2.2;
          const bx2 = bb.x + Math.sin(bb.phase) * bb.wob * 2.4;
